%Numerical simulations of a bacteria-immune model of meningitis
%  Within-host model of bacterial meningitis in the CSF:
%     B(t) = bacterial concentration (CFU/mL)
%     I(t) = immune response, measured as the CSF interleukin-6 (IL-6) concentration (pg/mL)
%
%     dB/dt = r*B*(1 - B/K) - k*B*I               (1)  logistic growth minus immune killing
%     dI/dt = s*B/(h + B) - d*(I - I0)            (2)  saturating IL-6 production minus
%                                                      decay back to the baseline level I0
%
%  What this script does
%     1. Convergence: simulates the model from four different initial bacterial loads and
%        compares the result with the chronic equilibrium predicted analytically.
%     2. Threshold: simulates the model with immune killing below and above the threshold
%        r = k*I0 (persistence versus clearance).
%     3. Parameter effects: plots the equilibrium bacterial load against k, r and I0, with
%        the clearance thresholds marked.

clear; clc; close all

%%\ Parameters
r  = 15;            % bacterial growth rate (per day)
K  = 1e9;           % bacterial carrying capacity (CFU/mL)
I0 = 205.83;        % baseline CSF IL-6 (pg/mL)
Is = 3538.69;       % CSF IL-6 at the persistent equilibrium (pg/mL)
Bs = 1e6;           % bacterial load at the persistent equilibrium (CFU/mL) 
h  = 1e6;           % half-saturation constant (CFU/mL)
d = 0.5;            % IL-6 decay rate (per day)
B0 = 1e3;

%%\ Calibrated parameters
k = r*(1 - Bs/K)/Is               % immune killing rate (mL/(pg*day)) %[output:07307447]
s = d*(Is - I0)*(h + Bs)/Bs        % maximum IL-6 production rate (pg/(mL day)) %[output:11502f50]

Bee = Beq(r, k, I0, K, s, d, h);
Iee = I0 + (s/d)*Bee/(h + Bee);

rhs  = @(t,Y,r,k) [r*Y(1)*(1 - Y(1)/K) - k*Y(1)*Y(2);
    s*Y(1)/(h + Y(1)) - d*(Y(2) - I0)];

% Solver settings: tight tolerances; B and I are kept non-negative
opts = odeset('RelTol',1e-8, 'AbsTol',[1e-6 1e-8], 'NonNegative',[1 2]);

%%\ Convergence to the chronic equilibrium from different initial bacterial loads
B0list = [1e2 1e3 1e5 1e8];
figure %[output:414e8608]
tiledlayout(1,2,'TileSpacing','compact'); %[output:414e8608]
ax1 = nexttile; hold on %[output:414e8608]
ax2 = nexttile; hold on %[output:414e8608]
for i = 1:numel(B0list)
    [t,Y] = ode45(@(t,Y) rhs(t,Y,r,k), [0 30], [B0list(i); I0], opts);
    plot(ax1, t, Y(:,1), 'LineWidth', 1.8); %[output:414e8608]
    plot(ax2, t, Y(:,2), 'LineWidth', 1.8);
end
yline(ax1, Bee, 'k--');  yline(ax2, Iee, 'k--'); %[output:414e8608]
set(ax1, 'YScale', 'log'); %[output:414e8608]
xlim(ax1, [0 30]);  xlim(ax2, [0 30]); %[output:414e8608]
xlabel(ax1,'Time (days)');  ylabel(ax1,'B (CFU/mL)');  title(ax1,'Bacteria'); %[output:414e8608]
xlabel(ax2,'Time (days)');  ylabel(ax2,'I (pg/mL)');    title(ax2,'Immune response'); %[output:414e8608]
legend(ax1, arrayfun(@(x) sprintf('B(0) = %g',x), B0list, 'UniformOutput', false), 'Location','southeast'); %[output:414e8608]
grid(ax1,'on');  grid(ax2,'on'); %[output:414e8608]
[~,Y] = ode45(@(t,Y) rhs(t,Y,r,k), [0 200], [B0; I0], opts);
fprintf('Simulated end: B = %.6g, I = %.4f\n', Y(end,1), Y(end,2)); %[output:0e52c76a]
fprintf('Predicted EE:  B = %.6g, I = %.4f\n', Bee, Iee); %[output:1e86ea86]
%%\ Simulation on both sides of the threshold r = k*I0
k_high = 1.5*r/I0;
[t1,Y1] = ode45(@(t,Y) rhs(t,Y,r,k),      [0 10], [1e6; I0], opts);
[t2,Y2] = ode45(@(t,Y) rhs(t,Y,r,k_high), [0 10], [1e6; I0], opts);
figure %[output:3f71dddb]
tiledlayout(1,2,'TileSpacing','compact'); %[output:3f71dddb]
nexttile; hold on %[output:3f71dddb]
plot(t1, max(Y1(:,1),1e-12), 'b', 'LineWidth', 2); %[output:3f71dddb]
plot(t2, max(Y2(:,1),1e-12), 'r', 'LineWidth', 2); %[output:3f71dddb]
set(gca,'YScale','log'); grid on %[output:3f71dddb]
xlabel('Time (days)');  ylabel('B (CFU/mL)');  title('Bacteria'); %[output:3f71dddb]
legend(sprintf('k = %.4f (r > kI_0)',k), sprintf('k = %.4f (r < kI_0)',k_high), 'Location','best'); %[output:3f71dddb]
nexttile; hold on %[output:3f71dddb]
plot(t1, Y1(:,2), 'b', 'LineWidth', 2); %[output:3f71dddb]
plot(t2, Y2(:,2), 'r', 'LineWidth', 2); %[output:3f71dddb]
grid on %[output:3f71dddb]
xlabel('Time (days)');  ylabel('I (pg/mL)');  title('Immune response'); %[output:3f71dddb]
fprintf('k = %.4f: end B = %.4g, I = %.2f\n', k,      Y1(end,1), Y1(end,2)); %[output:7161fcda]
fprintf('k = %.4f: end B = %.4g, I = %.2f\n', k_high, Y2(end,1), Y2(end,2)); %[output:80396cc2]

%%\ Effect of k, r and I0 on the equilibrium (values below 1 CFU/mL plotted as 1)
kv = logspace(-4, -1, 400);
rv = linspace(0.01, 20, 400);
Iv = linspace(1, 6000, 400);

figure %[output:4fd8bb7b]
tiledlayout(1,3,'TileSpacing','compact'); %[output:4fd8bb7b]
nexttile %[output:4fd8bb7b]
plot(kv, max(Beq(r,kv,I0,K,s,d,h),1), 'LineWidth', 2);  xline(r/I0, '--'); %[output:4fd8bb7b]
set(gca,'XScale','log','YScale','log');  xlabel('k (mL/(pg day))');  ylabel('B^* (CFU/mL)');  grid on %[output:4fd8bb7b]
nexttile %[output:4fd8bb7b]
plot(rv, max(Beq(rv,k,I0,K,s,d,h),1), 'LineWidth', 2);  xline(k*I0, '--'); %[output:4fd8bb7b]
set(gca,'YScale','log');  xlabel('r (per day)');  grid on %[output:4fd8bb7b]
nexttile %[output:4fd8bb7b]
plot(Iv, max(Beq(r,k,Iv,K,s,d,h),1), 'LineWidth', 2);  xline(r/k, '--'); %[output:4fd8bb7b]
set(gca,'YScale','log');  xlabel('I_0 (pg/mL)');  grid on %[output:4fd8bb7b]

fprintf('Clearance thresholds (DFE stable beyond these):\n'); %[output:8128efc8]
fprintf('  k  > r/I0 = %.4f   (current k = %.4f)\n', r/I0, k); %[output:33c77f42]
fprintf('  r  < k*I0 = %.4f   (current r = %.1f)\n', k*I0, r); %[output:5149ca53]
fprintf('  I0 > r/k  = %.1f   (current I0 = %.2f)\n', r/k, I0); %[output:79619851]

%%\ Local functions
function B = Beq(r, k, I0, K, s, d, h)
a  = r/K;
b  = -(r*(1 - h/K) - k.*I0 - k.*s/d);
c  = -(r - k.*I0)*h;
sg = 2*(b >= 0) - 1;
q  = -(b + sg.*sqrt(b.^2 - 4*a.*c))/2;
B  = max(q./a, c./q);
B(r <= k.*I0) = 0;
end

